// Turns an old-layout revision of the root AGENTS.md, scripts/e2e/README.md (the live proofs) and
// docs/kubernetes.md (the Kubernetes guide) into the new layout (INFRA-632), so the change is
// regenerated by a script and never re-done by hand.
//
//   bun .legion/INFRA-632/restructure.ts (--strict|--lenient) [--structural-only]
//     [--report <report.json>] [--line-breaks <path to semantic-line-breaks.ts>]
//     [<input.md> <output.md>]...
//
// With no file pairs it rewrites the workspace's three files in place. A file is recognised by its
// first line. Steps, per file, in order:
//
//   1. AGENTS.md's `## Commands` fences become lists, one item per `<command>  # <description>`
//      line: the command as a code span, the description as the item's second paragraph, with
//      each token Markdown would read differently put in a code span (a rule, convertCommands);
//   2. every table the checker finds a row of two sentences, or longer than one screen, in becomes
//      a list, one item per row, the header row replaced by one sentence (a rule, convertTables);
//   3. hand-written enumerations that every new item edits become lists (ENUMERATIONS, the probe
//      command of TOOLCHAIN_PROBE, the capability check's tools of CAPABILITY_TOOLS);
//   4. AGENTS.md's five lifecycle lines become paragraphs, and its closing quote holds one
//      sentence per line (LIFECYCLE, BLOCKQUOTE);
//   5. each file gets the layout instruction under its title (HEAD_NOTES);
//   6. AGENTS.md's Conventions get the layout rule (CONVENTION);
//   7. words that pointed at a converted table, a moved sentence or a position in a list are
//      reworded (REWORDINGS), and each line break inside a code span that starts a line with a
//      block-level tag, which opens a raw HTML block mid-paragraph, becomes a space
//      (HTML_BLOCK_JOINS);
//   8. scripts/semantic-line-breaks.ts --write re-lays out the result (whitespace only);
//   9. items still longer than one screen are split at a sentence that starts a new topic, into
//      sibling items, or into an item nested in it when the item is a numbered step, so no step is
//      added; a one-sentence item's clauses after `; ` become items nested in it (SPLITS);
//  10. scripts/semantic-line-breaks.ts --write again, then the same script checks the result.
//
// The rules (steps 1, 2 and the lifecycle blank lines) need no anchor, so main's daily edits do
// not break them; every other edit is anchored by text, never by line number. --strict fails,
// writing nothing, on any anchor that is missing or not unique, on any refusal of steps 8 and 10,
// on any finding of step 10 and on any warning the checker prints; --lenient warns and skips the
// edit, so an open pull request can port its old-layout files onto the new layout. When --write
// refuses a file, --lenient writes that output as it stood before the refused step, warns, writes
// the other outputs as usual and exits 2. --structural-only writes the result of steps 1-7, the
// intermediate commit a reviewer reads. --report writes a JSON array of every edit, in the order it
// was made: { id, kind, file, old, new }, where `old` is the exact text the edit replaced, with
// enough words around it to occur once in the text folded to single spaces, and `new` what
// replaced it, so applying each folded `old` -> folded `new` to the folded input yields the folded
// output. Steps 8 and 10 change only whitespace and have no entry, and neither has the indentation
// a nesting edit gives the lines it moves into the nested item.
import { spawnSync } from "node:child_process";
import { mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";

type Guide = "agents" | "e2e" | "kubernetes";

const REPO_ROOT = resolve(import.meta.dir, "../..");

const GUIDES: Record<Guide, { title: string; path: string }> = {
  agents: { title: "# Legion", path: "AGENTS.md" },
  e2e: { title: "# Live proofs", path: "scripts/e2e/README.md" },
  kubernetes: { title: "# Legion on Kubernetes", path: "docs/kubernetes.md" },
};

const USAGE =
  "usage: bun .legion/INFRA-632/restructure.ts (--strict|--lenient) [--structural-only] " +
  "[--report <report.json>] [--line-breaks <semantic-line-breaks.ts>] [<input.md> <output.md>]...\n";

type Kind =
  | "table-intro"
  | "table-row"
  | "commands-fence"
  | "commands-item"
  | "enumeration"
  | "lifecycle"
  | "blockquote"
  | "head-note"
  | "conventions"
  | "rewording"
  | "html-block"
  | "split";

// ---------------------------------------------------------------------------------------------
// The named edits and the rules' data.
// ---------------------------------------------------------------------------------------------

