// ---------------------------------------------------------------------------------------------
// Text helpers and the editor that records the report.
// ---------------------------------------------------------------------------------------------

interface Problem {
  id: string;
  anchor: string;
  message: string;
}

interface Entry {
  id: string;
  kind: Kind;
  file: string;
  old: string;
  new: string;
}

const ITEM_START = /^([ \t]*)([-*+]|\d{1,9}[.)])([ \t]+)/;
const HEADING = /^#{1,6}(?:[ \t]|$)/;
const FENCE = /^[ \t]*(`{3,}|~{3,})/;
const DELIMITER_ROW = /^[ \t]*\|?[ \t]*:?-+:?[ \t]*(?:\|[ \t]*:?-+:?[ \t]*)*\|?[ \t]*$/;
const TABLE_LINE = /^ {0,3}\|/;
const CLOSERS = ")]\"'*_”’";
const WHITESPACE = /\s/;

function fold(text: string): string {
  return text.replace(/\s+/g, " ").trim();
}

/** The anchor as a pattern: its words escaped, any run of whitespace standing for each space. */
function anchorPattern(anchor: string): string {
  const words = anchor.trim().split(/\s+/);
  return words.map((word) => word.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("\\s+");
}

function isBlank(line: string | undefined): boolean {
  return line === undefined || line.trim() === "";
}

function indentLength(line: string): number {
  return /^[ \t]*/.exec(line)?.[0].length ?? 0;
}

function occurrences(haystack: string, needle: string): number {
  let count = 0;
  for (let at = haystack.indexOf(needle); at !== -1; at = haystack.indexOf(needle, at + 1)) {
    count++;
    if (count > 1) break;
  }
  return count;
}

/** Offset of the start of each line, and one past the end. */
function lineStarts(text: string): number[] {
  const starts = [0];
  for (let at = text.indexOf("\n"); at !== -1; at = text.indexOf("\n", at + 1)) {
    starts.push(at + 1);
  }
  starts.push(text.length + 1);
  return starts;
}

/**
 * The text an edit replaced and what replaced it, widened word by word on both sides until the
 * folded old text occurs exactly once in the folded file: at least one whole word of context on
 * each side, so the folded replacement joins the folded file exactly as the edit did.
 */
function reportSpan(
  text: string,
  start: number,
  end: number,
  replacement: string
): { old: string; next: string } {
  const space = (at: number): boolean => WHITESPACE.test(text[at] ?? "");
  let left = start;
  let right = end;
  while (left > 0 && !space(left - 1)) left--;
  while (right < text.length && !space(right)) right++;
  const widen = (): void => {
    while (left > 0 && space(left - 1)) left--;
    while (left > 0 && !space(left - 1)) left--;
    while (right < text.length && space(right)) right++;
    while (right < text.length && !space(right)) right++;
  };
  widen();
  const folded = fold(text);
  for (;;) {
    const old = text.slice(left, right);
    if (occurrences(folded, fold(old)) === 1 || (left === 0 && right === text.length)) {
      return { old, next: text.slice(left, start) + replacement + text.slice(end, right) };
    }
    widen();
  }
}

class Editor {
  readonly entries: Entry[] = [];
  constructor(
    public text: string,
    readonly file: string
  ) {}

  replace(start: number, end: number, replacement: string, id: string, kind: Kind): void {
    const { old, next } = reportSpan(this.text, start, end, replacement);
    this.entries.push({ id, kind, file: this.file, old, new: next });
    this.text = this.text.slice(0, start) + replacement + this.text.slice(end);
  }
}

interface Span {
  start: number;
  end: number;
  replacement: string;
  id: string;
  kind: Kind;
}

/** Applies spans computed on one text, last first, so the earlier offsets stay valid. */
function applySpans(editor: Editor, spans: Span[]): void {
  for (const span of [...spans].sort((a, b) => b.start - a.start)) {
    editor.replace(span.start, span.end, span.replacement, span.id, span.kind);
  }
}

/** The marker of an item a nesting edit adds, and so the columns its content is indented past it. */
const NESTED_MARKER = "- ";

/**
 * Offset of the first line after the one holding `from` that is outside the list item whose
 * content column is `column` (indented less, after a blank line or opening an item or heading), or
 * the text's end.
 */
function itemEnd(text: string, from: number, column: number): number {
  let blank = false;
  for (let at = text.indexOf("\n", from) + 1; at > 0 && at < text.length; ) {
    const end = text.indexOf("\n", at);
    const line = text.slice(at, end === -1 ? undefined : end);
    if (isBlank(line)) {
      blank = true;
    } else {
      const indent = indentLength(line);
      if (indent < column && (blank || ITEM_START.test(line) || HEADING.test(line))) return at;
      blank = false;
    }
    if (end === -1) break;
    at = end + 1;
  }
  return text.length;
}

/**
 * Indents by `by` more columns each non-blank line after the one holding offset `from`, up to the
 * line holding offset `to`, not included, except a line starting with `keep` (an item marker the
 * edit wrote at its place): the lines a nesting edit moves into the nested item. Whitespace only,
 * so it has no report entry.
 */
function indentBetween(editor: Editor, from: number, to: number, by: number, keep?: string): void {
  const text = editor.text;
  const first = text.indexOf("\n", from) + 1;
  const last = text.lastIndexOf("\n", to - 1) + 1;
  if (first === 0 || first >= last) return;
  const body = text
    .slice(first, last)
    .split("\n")
    .map((line) =>
      isBlank(line) || (keep && line.startsWith(keep)) ? line : " ".repeat(by) + line
    )
    .join("\n");
  editor.text = text.slice(0, first) + body + text.slice(last);
}

/** A code span holding the text, its delimiter longer than any backtick run inside. */
function codeSpan(text: string): string {
  const longest = Math.max(0, ...(text.match(/`+/g) ?? []).map((run) => run.length));
  const delimiter = "`".repeat(longest + 1);
  const pad = text.startsWith("`") || text.endsWith("`") ? " " : "";
  return `${delimiter}${pad}${text}${pad}${delimiter}`;
}

/** The text cut into code spans and the text between them, as CommonMark reads backtick runs. */
function codeSegments(text: string): { code: boolean; text: string }[] {
  const segments: { code: boolean; text: string }[] = [];
  let plain = "";
  let at = 0;
  while (at < text.length) {
    if (text[at] === "\\" && text[at + 1] === "`") {
      plain += text.slice(at, at + 2);
      at += 2;
      continue;
    }
    if (text[at] !== "`") {
      plain += text[at];
      at++;
      continue;
    }
    let run = 0;
    while (text[at + run] === "`") run++;
    let close = at + run;
    for (;;) {
      close = text.indexOf("`".repeat(run), close);
      if (close === -1) break;
      let length = 0;
      while (text[close + length] === "`") length++;
      if (length === run) break;
      close += length;
    }
    if (close === -1) {
      plain += "`".repeat(run);
      at += run;
      continue;
    }
    if (plain !== "") segments.push({ code: false, text: plain });
    plain = "";
    segments.push({ code: true, text: text.slice(at, close + run) });
    at = close + run;
  }
  if (plain !== "") segments.push({ code: false, text: plain });
  return segments;
}

// ---------------------------------------------------------------------------------------------
// Step 1: the Commands fences.
// ---------------------------------------------------------------------------------------------

const COMMAND_LINE = /^(\S.*?)[ \t]{2,}# (.*)$/;
/** A token Markdown would read otherwise than the fence showed it. */
const NEEDS_CODE = /[<>*|\\]|^@/;
/** The subcommand list step 3 turns into a list of its own (ENUMERATIONS). */
const SUBCOMMAND_LIST = /^version(?:\|[a-z][a-z-]*)+$/;
const LEADING_PUNCTUATION = /^[("[]+/;
const TRAILING_PUNCTUATION = /[,;.):"\]]+$/;
/** Text that would open a block at the start of a paragraph. */
const BLOCK_START =
  /^(?:[-+*](?:\s|$)|#{1,6}(?:\s|$)|[>|]|\d{1,9}[.)](?:\s|$)|`{3}|~{3}|<[A-Za-z/!?])/;

/**
 * The description as Markdown: each whitespace-delimited token outside a code span that holds `<`,
 * `>`, `*`, `|` or `\`, or starts with `@`, goes into a code span, a `<…>` placeholder with spaces
 * in it taken whole; punctuation before or after the token stays outside.
 */
function escapeDescription(description: string): string | { problem: string } {
  const segments = codeSegments(description);
  let out = "";
  for (const [n, segment] of segments.entries()) {
    if (segment.code) {
      out += segment.text;
      continue;
    }
    const text = segment.text;
    let at = 0;
    while (at < text.length) {
      if (WHITESPACE.test(text[at] ?? "")) {
        out += text[at];
        at++;
        continue;
      }
      let end = at;
      let angle = false;
      while (end < text.length && (angle || !WHITESPACE.test(text[end] ?? ""))) {
        if (text[end] === "<" && text.indexOf(">", end) !== -1) angle = true;
        if (text[end] === ">") angle = false;
        end++;
      }
      const token = text.slice(at, end);
      const lead = LEADING_PUNCTUATION.exec(token)?.[0] ?? "";
      const trail = TRAILING_PUNCTUATION.exec(token.slice(lead.length))?.[0] ?? "";
      const core = token.slice(lead.length, token.length - trail.length);
      if (core !== "" && NEEDS_CODE.test(core) && !SUBCOMMAND_LIST.test(core)) {
        const touchesCode =
          (at === 0 && lead === "" && segments[n - 1]?.code) ||
          (end === text.length && trail === "" && segments[n + 1]?.code);
        if (touchesCode) return { problem: `${JSON.stringify(token)} touches a code span` };
        out += `${lead}${codeSpan(core)}${trail}`;
      } else {
        out += token;
      }
      at = end;
    }
  }
  return out;
}

function convertCommands(editor: Editor, problems: Problem[]): void {
  const lines = editor.text.split("\n");
  const starts = lineStarts(editor.text);
  const heading = lines.indexOf("## Commands");
  if (heading === -1) {
    problems.push({ id: "commands", anchor: "## Commands", message: "missing" });
    return;
  }
  let end = heading + 1;
  while (end < lines.length && !/^## /.test(lines[end] ?? "")) end++;
  const spans: Span[] = [];
  const at = (line: number): number => starts[line] ?? editor.text.length;
  for (let index = heading + 1; index < end; index++) {
    const run = FENCE.exec(lines[index] ?? "")?.[1];
    if (run === undefined) continue;
    let close = index + 1;
    while (close < end && (lines[close] ?? "").trim() !== run) close++;
    if (close === end) {
      problems.push({ id: "commands", anchor: lines[index] ?? "", message: "fence never closes" });
      return;
    }
    spans.push({
      start: at(index),
      end: at(index + 1),
      replacement: "",
      id: "commands-fence-open",
      kind: "commands-fence",
    });
    for (let line = index + 1; line < close; line++) {
      const text = lines[line] ?? "";
      const match = COMMAND_LINE.exec(text);
      if (match === null) {
        problems.push({
          id: "commands-item",
          anchor: text,
          message: "not of the form `<command>  # <description>`",
        });
        continue;
      }
      const [, command = "", description = ""] = match;
      const escaped = escapeDescription(description.trim());
      if (typeof escaped !== "string") {
        problems.push({ id: "commands-item", anchor: command, message: escaped.problem });
        continue;
      }
      if (BLOCK_START.test(escaped)) {
        problems.push({
          id: "commands-item",
          anchor: command,
          message: "the description would open a block",
        });
        continue;
      }
      const separator = line + 1 < close ? "\n" : "";
      spans.push({
        start: at(line),
        end: at(line) + text.length,
        replacement: `- ${codeSpan(command.trim())}\n\n  ${escaped}${separator}`,
        id: "commands-item",
        kind: "commands-item",
      });
    }
    spans.push({
      start: at(close),
      end: Math.min(at(close + 1), editor.text.length),
      replacement: "",
      id: "commands-fence-close",
      kind: "commands-fence",
    });
    index = close;
  }
  applySpans(editor, spans);
}

// ---------------------------------------------------------------------------------------------
// Step 2: tables.
// ---------------------------------------------------------------------------------------------

/**
 * The cells of a table row: split at each `|` not escaped, the outer pipes dropped, trimmed. Given
 * the header's cell count, a `|` past the last column's start stays in the last cell: GitHub drops
 * a cell past the header's count, so such a `|` is one the author meant inside a code span.
 */
function rowCells(line: string, count = Number.POSITIVE_INFINITY): string[] {
  let row = line.trim();
  if (row.startsWith("|")) row = row.slice(1);
  if (row.endsWith("|") && !row.endsWith("\\|")) row = row.slice(0, -1);
  const cells = row.split(/(?<!\\)\|/);
  if (cells.length > count) cells.splice(count - 1, cells.length, cells.slice(count - 1).join("|"));
  return cells.map((cell) => cell.trim());
}

/**
 * Inside a code span a table cell's `\|` is GFM's escape for `|`, which a list item would render
 * literally, so it becomes `|`; a `\|` outside code renders as `|` anywhere and stays.
 */
function unescapeCodePipes(cell: string): string {
  return codeSegments(cell)
    .map((segment) => (segment.code ? segment.text.replaceAll("\\|", "|") : segment.text))
    .join("");
}

interface FoundTable {
  first: number;
  last: number;
  section: string;
  header: string[];
}

/** Whether each line opens, sits inside or closes fenced code. */
function fencedLines(lines: readonly string[]): boolean[] {
  const fenced: boolean[] = [];
  let fence: string | undefined;
  for (const line of lines) {
    const run = FENCE.exec(line)?.[1];
    if (fence !== undefined) {
      fenced.push(true);
      if (run?.startsWith(fence) && line.trim() === run) fence = undefined;
      continue;
    }
    if (run !== undefined) fence = run;
    fenced.push(run !== undefined);
  }
  return fenced;
}

/** Every pipe table outside fences, with the heading it sits under. */
function findTables(lines: readonly string[]): FoundTable[] {
  const tables: FoundTable[] = [];
  const fenced = fencedLines(lines);
  let section = "";
  for (let index = 0; index < lines.length; index++) {
    if (fenced[index]) continue;
    const line = lines[index] ?? "";
    if (HEADING.test(line)) section = line.trim();
    if (!TABLE_LINE.test(line) || !DELIMITER_ROW.test(lines[index + 1] ?? "")) continue;
    let last = index + 1;
    while (TABLE_LINE.test(lines[last + 1] ?? "")) last++;
    tables.push({ first: index, last, section, header: rowCells(line) });
    index = last;
  }
  return tables;
}

interface TableReport {
  line: number;
  section: string;
  header: string;
  converted: boolean;
}

/**
 * Converts every table the checker finds an R1 or R3 row in (`failing` holds 0-based line
 * numbers of the text as it stands); the others stay tables.
 */
function convertTables(
  editor: Editor,
  failing: ReadonlySet<number>,
  tablesSeen: TableReport[],
  problems: Problem[],
  warnings: string[]
): void {
  const lines = editor.text.split("\n");
  const starts = lineStarts(editor.text);
  const spans: Span[] = [];
  for (const table of findTables(lines)) {
    const signature = table.header.join(" | ");
    let fails = false;
    for (let line = table.first; line <= table.last; line++) fails ||= failing.has(line);
    tablesSeen.push({
      line: table.first + 1,
      section: table.section,
      header: signature,
      converted: fails,
    });
    if (!fails) continue;
    const id = `table ${table.section} | ${signature} |`;
    let intro = TABLE_INTROS[signature];
    if (intro === undefined) {
      intro = `Each item below gives the ${table.header.slice(0, -1).join(", ")} of one entry, then its ${table.header.at(-1)}.`;
      warnings.push(
        `line ${table.first + 1}: the table under ${table.section} with header "${signature}" has no sentence in TABLE_INTROS; its intro reads "${intro}"`
      );
    }
    const rows: Span[] = [];
    let ok = true;
    for (let line = table.first + 2; line <= table.last; line++) {
      const row = lines[line] ?? "";
      const cells = rowCells(row, table.header.length).map(unescapeCodePipes);
      if (cells.length !== table.header.length) {
        problems.push({
          id,
          anchor: row,
          message: `row has ${cells.length} cells, the header ${table.header.length}`,
        });
        ok = false;
        break;
      }
      if (rowCells(row).length > cells.length) {
        warnings.push(
          `line ${line + 1}: a row of the table under ${table.section} holds an unescaped \`|\`, which GitHub reads as a cell it drops; it stays in the item's last paragraph`
        );
      }
      const key = cells.slice(0, -1).join(" — ");
      const prose = cells.at(-1) ?? "";
      if (BLOCK_START.test(key) || BLOCK_START.test(prose)) {
        problems.push({ id, anchor: lines[line] ?? "", message: "a cell would open a block" });
        ok = false;
        break;
      }
      const item = `- ${key}${prose === "" ? "" : `\n\n  ${prose}`}`;
      rows.push({
        start: starts[line] ?? 0,
        end: (starts[line] ?? 0) + (lines[line] ?? "").length,
        replacement: line < table.last ? `${item}\n` : item,
        id: `table-row ${table.section} | ${cells[0]}`,
        kind: "table-row",
      });
    }
    if (!ok) continue;
    if (/^[ \t]/.test(lines[table.first] ?? "")) {
      problems.push({ id, anchor: lines[table.first] ?? "", message: "an indented table" });
      continue;
    }
    const before = isBlank(lines[table.first - 1]) ? "" : "\n";
    const after = isBlank(lines[table.last + 1]) ? "" : "\n";
    const headerStart = starts[table.first] ?? 0;
    spans.push({
      start: headerStart,
      end: (starts[table.first + 1] ?? 0) + (lines[table.first + 1] ?? "").length,
      replacement: `${before}${intro}\n`,
      id: `table-intro ${table.section} | ${signature} |`,
      kind: "table-intro",
    });
    spans.push(...rows);
    const lastRow = rows.at(-1);
    if (after !== "" && lastRow !== undefined) lastRow.replacement += after;
  }
  applySpans(editor, spans);
}

// ---------------------------------------------------------------------------------------------
// Steps 3 to 7: the named edits.
// ---------------------------------------------------------------------------------------------

/** The one match of the anchor, or a problem naming it. */
function uniqueMatch(
  text: string,
  anchor: string,
  id: string,
  problems: Problem[]
): RegExpExecArray | undefined {
  const found = [...text.matchAll(new RegExp(anchorPattern(anchor), "g"))];
  if (found.length !== 1) {
    problems.push({
      id,
      anchor,
      message: found.length === 0 ? "missing" : `${found.length} matches`,
    });
    return undefined;
  }
  return found[0];
}

function applyEnumerations(editor: Editor, guide: Guide, problems: Problem[]): void {
  for (const edit of ENUMERATIONS.filter((candidate) => candidate.guide === guide)) {
    const match = uniqueMatch(editor.text, edit.old, edit.id, problems);
    if (match === undefined) continue;
    let end = match.index + match[0].length;
    let replacement = edit.new;
    if (edit.nestFollowing) {
      const text = editor.text;
      if (text[end] !== "\n" || isBlank(text.slice(end + 1, text.indexOf("\n", end + 1)))) {
        problems.push({
          id: edit.id,
          anchor: edit.old,
          message: "no list follows on the next line",
        });
        continue;
      }
      let stop = text.indexOf("\n\n", end + 1);
      if (stop === -1) stop = text.length;
      const nested = text
        .slice(end + 1, stop)
        .split("\n")
        .map((line) => (line === "" ? line : `  ${line}`))
        .join("\n");
      replacement += `\n${nested}`;
      end = stop;
    }
    editor.replace(match.index, end, replacement, edit.id, "enumeration");
  }
  if (TOOLCHAIN_PROBE.guide === guide) applyToolchainProbe(editor, problems);
  if (CAPABILITY_TOOLS.guide === guide) applyItemBreaks(editor, problems);
}

function applyToolchainProbe(editor: Editor, problems: Problem[]): void {
  const probe = TOOLCHAIN_PROBE;
  const match = uniqueMatch(editor.text, probe.open, probe.id, problems);
  if (match === undefined) return;
  const bodyStart = match.index + match[0].length;
  const close = editor.text.indexOf(probe.close, bodyStart);
  if (close === -1) {
    problems.push({ id: probe.id, anchor: probe.close, message: "missing after the probe" });
    return;
  }
  const commands = editor.text
    .slice(bodyStart, close)
    .trim()
    .split(/\s+&&\s+/);
  const body = commands.map(
    (command, n) => `  ${fold(command)}${n < commands.length - 1 ? " &&" : ""}`
  );
  let start = match.index;
  let lead = "";
  if (editor.text[start - 1] === "\n") {
    start--;
    lead = "\n\n";
  }
  const block = `${lead}\`\`\`sh\n${fold(match[0].slice(1))}\n${body.join("\n")}'\n\`\`\``;
  editor.replace(start, close + probe.close.length, block, probe.id, "enumeration");
}

/**
 * CAPABILITY_TOOLS: each break's separator dropped and its item of the list nested in the bullet
 * begun, or the bullet's paragraph after that list; then the nested items' continuation lines are
 * indented to their content column. The breaks are in the text's order, so an offset taken before
 * a later break stays valid.
 */
function applyItemBreaks(editor: Editor, problems: Problem[]): void {
  const { id, breaks } = CAPABILITY_TOOLS;
  let pad: string | undefined;
  let nested: number | undefined;
  let paragraph: number | undefined;
  for (const cut of breaks) {
    const match = uniqueMatch(editor.text, cut.anchor, id, problems);
    if (match === undefined) continue;
    const before = editor.text.slice(0, match.index).trimEnd();
    let start = before.length;
    if (cut.drop !== "") {
      const separator = new RegExp(`${anchorPattern(cut.drop)}$`).exec(before);
      if (separator === null) {
        problems.push({ id, anchor: cut.anchor, message: `not after ${JSON.stringify(cut.drop)}` });
        continue;
      }
      start = separator.index;
    }
    if (pad === undefined) {
      const lines = before.split("\n");
      const bullet = itemStartAbove(lines);
      if (typeof bullet === "string") {
        problems.push({ id, anchor: cut.anchor, message: bullet });
        return;
      }
      pad = " ".repeat(ITEM_START.exec(lines[bullet] ?? "")?.[0].length ?? 0);
    }
    const marker = "paragraph" in cut ? "" : NESTED_MARKER;
    editor.replace(
      start,
      match.index,
      `\n\n${pad}${marker}`,
      `${id}: ${cut.anchor}`,
      "enumeration"
    );
    if (marker === "") paragraph = start;
    else nested ??= start;
  }
  if (pad === undefined || nested === undefined) return;
  const end = paragraph === undefined ? itemEnd(editor.text, nested, pad.length) : paragraph + 2;
  indentBetween(editor, nested, end, NESTED_MARKER.length, `${pad}${NESTED_MARKER}`);
}

function applyLifecycle(editor: Editor, problems: Problem[]): void {
  const lines = editor.text.split("\n");
  const at = LIFECYCLE.labels.map((label) => lines.findIndex((line) => line.startsWith(label)));
  for (const label of LIFECYCLE.labels) {
    if (lines.filter((line) => line.startsWith(label)).length !== 1) {
      problems.push({ id: LIFECYCLE.id, anchor: label, message: "not one line starting so" });
      return;
    }
  }
  const starts = lineStarts(editor.text);
  const spans: Span[] = [];
  for (const index of at.slice(1)) {
    if (isBlank(lines[index - 1])) continue;
    const start = starts[index] ?? 0;
    spans.push({
      start: start - 1,
      end: start,
      replacement: "\n\n",
      id: LIFECYCLE.id,
      kind: "lifecycle",
    });
  }
  applySpans(editor, spans);
}

function applyBlockquote(editor: Editor, problems: Problem[]): void {
  const match = uniqueMatch(editor.text, BLOCKQUOTE.old, BLOCKQUOTE.id, problems);
  if (match === undefined) return;
  editor.replace(
    match.index,
    match.index + match[0].length,
    BLOCKQUOTE.new,
    BLOCKQUOTE.id,
    "blockquote"
  );
}

/**
 * The note goes after the first paragraph under the title, and after the list that paragraph
 * opens when it ends with a colon.
 */
function addHeadNote(editor: Editor, guide: Guide, problems: Problem[]): void {
  const note = HEAD_NOTES.find((candidate) => candidate.guide === guide);
  if (note === undefined) return;
  const sentences = headNote(guide, note.extra);
  const opening = sentences[0] ?? "";
  if (editor.text.includes(opening)) {
    problems.push({ id: note.id, anchor: opening, message: "the file carries the note already" });
    return;
  }
  const lines = editor.text.split("\n");
  let first = 1;
  while (first < lines.length && isBlank(lines[first])) first++;
  let last = first;
  while (last + 1 < lines.length && !isBlank(lines[last + 1])) last++;
  if (!fold(lines.slice(first, last + 1).join(" ")).endsWith(fold(note.after))) {
    problems.push({
      id: note.id,
      anchor: note.after,
      message: "not the end of the first paragraph under the title",
    });
    return;
  }
  if ((lines[last] ?? "").endsWith(":")) {
    for (let index = last + 1; index < lines.length; index++) {
      const line = lines[index] ?? "";
      if (isBlank(line)) continue;
      if (!ITEM_START.test(line) && !/^[ \t]/.test(line)) break;
      last = index;
    }
  }
  const starts = lineStarts(editor.text);
  const end = (starts[last] ?? 0) + (lines[last] ?? "").length;
  editor.replace(end, end, `\n\n${sentences.join("\n")}`, note.id, "head-note");
}

function addConvention(editor: Editor, problems: Problem[]): void {
  const name = CONVENTION.text.slice(0, CONVENTION.text.indexOf(" — "));
  if (editor.text.includes(name)) {
    problems.push({
      id: CONVENTION.id,
      anchor: name,
      message: "the file carries the rule already",
    });
    return;
  }
  const lines = editor.text.split("\n");
  const found = lines.flatMap((line, index) => (line.startsWith(CONVENTION.after) ? [index] : []));
  const index = found[0];
  if (found.length !== 1 || index === undefined) {
    const message = found.length === 0 ? "missing" : `${found.length} matches`;
    problems.push({ id: CONVENTION.id, anchor: CONVENTION.after, message });
    return;
  }
  let last = index;
  while (
    last + 1 < lines.length &&
    !isBlank(lines[last + 1]) &&
    !ITEM_START.test(lines[last + 1] ?? "")
  ) {
    last++;
  }
  const starts = lineStarts(editor.text);
  const end = (starts[last] ?? 0) + (lines[last] ?? "").length;
  editor.replace(end, end, `\n${CONVENTION.text}`, CONVENTION.id, "conventions");
}

function applyRewordings(editor: Editor, guide: Guide, problems: Problem[]): void {
  for (const edit of REWORDINGS.filter((candidate) => candidate.guide === guide)) {
    const match = uniqueMatch(editor.text, edit.find, edit.id, problems);
    if (match === undefined) continue;
    editor.replace(match.index, match.index + match[0].length, edit.replace, edit.id, "rewording");
  }
}

function applyHtmlBlockJoins(editor: Editor, guide: Guide, problems: Problem[]): void {
  for (const edit of HTML_BLOCK_JOINS.filter((candidate) => candidate.guide === guide)) {
    const anchor = `${edit.before} ${edit.after}`;
    const match = uniqueMatch(editor.text, anchor, edit.id, problems);
    if (match === undefined) continue;
    const gap = new RegExp(`^${anchorPattern(edit.before)}(\\s+)`).exec(match[0]);
    const whitespace = gap?.[1] ?? "";
    if (gap === null || !whitespace.includes("\n")) {
      problems.push({ id: edit.id, anchor, message: "no line break before the tag" });
      continue;
    }
    const start = match.index + gap[0].length - whitespace.length;
    editor.replace(start, start + whitespace.length, " ", edit.id, "html-block");
  }
}

// ---------------------------------------------------------------------------------------------
// Step 9: splits.
// ---------------------------------------------------------------------------------------------

/**
 * The line that opens the list item holding the last of the given lines, or a reason there is
 * none: the nearest marker line above, outside fenced code, whose content column is no deeper than
 * the last line's text.
 */
function itemStartAbove(lines: readonly string[]): number | string {
  const fenced = fencedLines(lines);
  const from = lines.length - 1;
  const last = ITEM_START.exec(lines[from] ?? "");
  const column = last === null ? indentLength(lines[from] ?? "") : last[0].length;
  for (let index = from; index >= 0; index--) {
    if (fenced[index]) continue;
    const line = lines[index] ?? "";
    const marker = ITEM_START.exec(line);
    if (marker !== null && marker[0].length <= column) return index;
    if (HEADING.test(line)) return "not inside a list item";
    if (!isBlank(line) && !/^[ \t]/.test(line) && isBlank(lines[index - 1]) && marker === null) {
      return "not inside a list item";
    }
  }
  return "not inside a list item";
}

function applySplits(editor: Editor, guide: Guide, problems: Problem[]): void {
  for (const split of SPLITS.filter((candidate) => candidate.guide === guide)) {
    const text = editor.text;
    const match = uniqueMatch(text, split.anchor, split.id, problems);
    if (match === undefined) continue;
    if (UNSPLIT_REGION.guide === guide) {
      const start = new RegExp(anchorPattern(UNSPLIT_REGION.start)).exec(text);
      const rest = start === null ? "" : text.slice(start.index);
      const end = start === null ? null : new RegExp(anchorPattern(UNSPLIT_REGION.end)).exec(rest);
      const inside =
        start !== null &&
        end !== null &&
        match.index >= start.index &&
        match.index <= start.index + end.index;
      if (inside) {
        problems.push({
          id: split.id,
          anchor: split.anchor,
          message: "inside the reclaim paragraph",
        });
        continue;
      }
    }
    let space = match.index;
    while (space > 0 && /[ \t\n]/.test(text[space - 1] ?? "")) space--;
    let mark = space - 1;
    if (split.clause) {
      if (space === match.index || text[mark] !== ";") {
        problems.push({ id: split.id, anchor: split.anchor, message: "does not follow a `; `" });
        continue;
      }
    } else {
      while (mark > 0 && CLOSERS.includes(text[mark] ?? "")) mark--;
      if (space === match.index || !".!?".includes(text[mark] ?? "")) {
        problems.push({ id: split.id, anchor: split.anchor, message: "does not start a sentence" });
        continue;
      }
    }
    const lines = text.slice(0, space).split("\n");
    const start = itemStartAbove(lines);
    if (typeof start === "string") {
      problems.push({ id: split.id, anchor: split.anchor, message: start });
      continue;
    }
    const [, indent = "", marker = "-", gap = " "] = ITEM_START.exec(lines[start] ?? "") ?? [];
    const from = split.clause ? space - 1 : space;
    // A numbered step's split nests in it, so the list keeps its count of steps.
    const nest = split.clause === "nest" || (split.clause === undefined && /\d/.test(marker));
    if (!nest) {
      editor.replace(from, match.index, `\n\n${indent}${marker}${gap}`, split.id, "split");
      continue;
    }
    const column = indent.length + marker.length + gap.length;
    editor.replace(
      from,
      match.index,
      `\n\n${" ".repeat(column)}${NESTED_MARKER}`,
      split.id,
      "split"
    );
    const markerLine = from + 2;
    indentBetween(
      editor,
      markerLine,
      itemEnd(editor.text, markerLine, column),
      NESTED_MARKER.length
    );
  }
}

// ---------------------------------------------------------------------------------------------
// The checker, the steps in order, and the command line.
// ---------------------------------------------------------------------------------------------

function runLineBreaks(
  lineBreaks: string,
  args: string[]
): { status: number; stdout: string; stderr: string } {
  const result = spawnSync(process.execPath, [lineBreaks, ...args], { encoding: "utf8" });
  if (result.error) throw result.error;
  return { status: result.status ?? 1, stdout: result.stdout, stderr: result.stderr };
}

function guideOf(text: string): Guide | undefined {
  const end = text.indexOf("\n");
  const title = text.slice(0, end === -1 ? undefined : end);
  return (Object.keys(GUIDES) as Guide[]).find((guide) => GUIDES[guide].title === title);
}

/** Ends the run with an exit status, once the scratch directory is removed. */
class Failure extends Error {
  constructor(
    message: string,
    readonly status: number
  ) {
    super(message);
  }
}

function fail(message: string, status: number): never {
  throw new Failure(message, status);
}

/** Runs the checker on the text and returns the 0-based lines it finds an R1 or R3 on. */
async function failingLines(lineBreaks: string, temp: string, text: string): Promise<Set<number>> {
  await writeFile(temp, text);
  const check = runLineBreaks(lineBreaks, [temp]);
  if (check.status > 1) {
    fail(`semantic-line-breaks.ts exited ${check.status}\n${check.stdout}${check.stderr}`, 2);
  }
  const lines = new Set<number>();
  for (const line of check.stdout.split("\n")) {
    const found = /:(\d+): R([13]):/.exec(line.slice(temp.length));
    if (line.startsWith(temp) && found) lines.add(Number(found[1]) - 1);
  }
  return lines;
}

async function main(argv: string[]): Promise<number> {
  let strict: boolean | undefined;
  let structuralOnly = false;
  let reportPath: string | undefined;
  let lineBreaks = join(REPO_ROOT, "scripts/semantic-line-breaks.ts");
  const paths: string[] = [];
  for (let index = 0; index < argv.length; index++) {
    const arg = argv[index] ?? "";
    if (arg === "--strict" || arg === "--lenient") {
      if (strict !== undefined) fail(USAGE, 2);
      strict = arg === "--strict";
    } else if (arg === "--structural-only") {
      structuralOnly = true;
    } else if (arg === "--line-breaks") {
      lineBreaks = resolve(argv[++index] ?? fail(USAGE, 2));
    } else if (arg === "--report") {
      reportPath = resolve(argv[++index] ?? fail(USAGE, 2));
    } else if (arg.startsWith("-")) {
      fail(USAGE, 2);
    } else {
      paths.push(arg);
    }
  }
  if (strict === undefined || paths.length % 2 !== 0) fail(USAGE, 2);
  const pairs: { input: string; output: string; name: string }[] = [];
  if (paths.length === 0) {
    for (const guide of Object.keys(GUIDES) as Guide[]) {
      const path = join(REPO_ROOT, GUIDES[guide].path);
      pairs.push({ input: path, output: path, name: GUIDES[guide].path });
    }
  }
  for (let index = 0; index < paths.length; index += 2) {
    const output = paths[index + 1] ?? "";
    pairs.push({ input: resolve(paths[index] ?? ""), output: resolve(output), name: output });
  }

  const scratch = await mkdtemp(join(tmpdir(), "infra-632-restructure-"));
  try {
    const results: { output: string; text: string }[] = [];
    const report: Entry[] = [];
    let failed = false;
    let refused = false;
    const level = strict ? "error" : "warning";
    const complain = (message: string): void => {
      process.stderr.write(`${message}\n`);
      if (strict) failed = true;
    };
    for (const [n, { input, output, name }] of pairs.entries()) {
      const text = await readFile(input, "utf8");
      const guide = guideOf(text);
      if (guide === undefined) {
        const titles = Object.values(GUIDES).map((entry) => `"${entry.title}"`);
        fail(
          `${input}: not one of the three guides (its first line is none of ${titles.join(", ")})\n`,
          2
        );
      }
      const temp = join(scratch, `${n}-${guide}.md`);
      const editor = new Editor(text, name);
      const problems: Problem[] = [];
      const warnings: string[] = [];
      const tables: TableReport[] = [];

      if (guide === "agents") convertCommands(editor, problems);
      convertTables(
        editor,
        await failingLines(lineBreaks, temp, editor.text),
        tables,
        problems,
        warnings
      );
      applyEnumerations(editor, guide, problems);
      if (guide === "agents") {
        applyLifecycle(editor, problems);
        applyBlockquote(editor, problems);
      }
      addHeadNote(editor, guide, problems);
      if (guide === "agents") addConvention(editor, problems);
      applyRewordings(editor, guide, problems);
      applyHtmlBlockJoins(editor, guide, problems);

      for (const table of tables) {
        process.stderr.write(
          `${input}: table under ${table.section}, "${table.header}" (line ${table.line} of the text step 2 reads): ${table.converted ? "converted" : "kept"}\n`
        );
      }
      for (const warning of warnings) process.stderr.write(`${input}: warning: ${warning}\n`);
      const reportProblems = (): void => {
        for (const problem of problems.splice(0)) {
          complain(
            `${input}: ${strict ? "error" : "warning, edit skipped"}: ${problem.id}: ${problem.message}: ${JSON.stringify(problem.anchor)}`
          );
        }
      };
      reportProblems();

      if (!structuralOnly) {
        const relayout = async (step: string): Promise<boolean> => {
          await writeFile(temp, editor.text);
          const write = runLineBreaks(lineBreaks, ["--write", temp]);
          for (const line of write.stderr
            .split("\n")
            .filter((entry) => entry.includes(": warning: "))) {
            complain(`${level}: ${line.replaceAll(temp, output)}`);
          }
          const refusal =
            write.status === 2 && write.stderr.includes(`${temp}: refusing to write: `);
          if (refusal) {
            const kept = strict
              ? "nothing is written"
              : `${output} holds the text before that step`;
            const why = write.stderr.replaceAll(temp, output).trimEnd();
            complain(
              `${level}: ${output}: semantic-line-breaks.ts --write refused it at step ${step}; ${kept}\n${why}`
            );
            refused = true;
            return false;
          }
          if (write.status !== 0) {
            fail(
              `${input}: semantic-line-breaks.ts --write exited ${write.status} at step ${step}\n${(write.stdout + write.stderr).replaceAll(temp, input)}`,
              write.status
            );
          }
          editor.text = await readFile(temp, "utf8");
          return true;
        };
        if (await relayout("8")) {
          applySplits(editor, guide, problems);
          reportProblems();
          if (await relayout("10")) {
            const check = runLineBreaks(lineBreaks, [temp]);
            if (check.status > 1) {
              fail(
                `${input}: semantic-line-breaks.ts exited ${check.status}\n${check.stdout}${check.stderr}`,
                check.status
              );
            }
            for (const line of `${check.stdout}${check.stderr}`.split("\n")) {
              if (line !== "") complain(`${level}: ${line.replaceAll(temp, output)}`);
            }
          }
        }
      }
      results.push({ output, text: editor.text });
      report.push(...editor.entries);
    }
    if (failed) {
      process.stderr.write("--strict: nothing written\n");
      return 1;
    }
    for (const { output, text } of results) {
      await mkdir(dirname(output), { recursive: true });
      await writeFile(output, text);
    }
    if (reportPath !== undefined) {
      await mkdir(dirname(reportPath), { recursive: true });
      await writeFile(reportPath, `${JSON.stringify(report, null, 2)}\n`);
    }
    return refused ? 2 : 0;
  } finally {
    await rm(scratch, { recursive: true, force: true });
  }
}

if (import.meta.main) {
  try {
    process.exit(await main(process.argv.slice(2)));
  } catch (error) {
    if (!(error instanceof Failure)) throw error;
    process.stderr.write(error.message);
    process.exit(error.status);
  }
}
